svg.script:
(function() {
  var svg;
  var scripts = document.getElementsByTagName('script');
  for (var i = scripts.length - 1; i >= 0; i--) {
    var node = scripts[i].parentNode;
    while (node) {
      if (node.tagName && node.tagName.toLowerCase() === 'svg') { svg = node; break; }
      node = node.parentNode;
    }
    if (svg) break;
  }
  if (!svg) return;

  var popupHeader = svg.querySelector('.popup-header');
  var popupFooter = svg.querySelector('.popup-footer');
  if (!popupHeader || !popupFooter) return;

  var ht = popupHeader.querySelector('.popup-total');
  var hh = popupHeader.querySelector('.popup-headword');
  var hs = popupHeader.querySelector('.popup-status');
  var f1 = popupFooter.querySelector('.popup-line1');
  var f2 = popupFooter.querySelector('.popup-line2');

  var hdrW = 300, hdrH = 50;
  var ftrW = 310, ftrH = 34;
  var vbW = 560, vbH = 170;

  function svgPoint(evt) {
    var pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  }

  function position(popup, pt, popupW, popupH) {
    var dx = (pt.x + 14 + popupW > vbW) ? -popupW - 14 : 14;
    var dy = (pt.y + 14 + popupH > vbH) ? -popupH - 14 : 14;
    var px = pt.x + dx;
    if (px < 2) px = 2;
    if (px + popupW > vbW - 2) px = vbW - popupW - 2;
    popup.setAttribute('transform', 'translate(' + px + ',' + (pt.y + dy) + ')');
  }

  var hdrHits = svg.querySelectorAll('.header-hit');
  for (var i = 0; i < hdrHits.length; i++) {
    (function(el) {
      el.addEventListener('mouseenter', function() {
        ht.textContent = el.getAttribute('data-total');
        hh.textContent = el.getAttribute('data-header');
        hs.textContent = el.getAttribute('data-status');
        popupHeader.style.opacity = '1';
        popupFooter.style.opacity = '0';
      });
      el.addEventListener('mousemove', function(evt) {
        position(popupHeader, svgPoint(evt), hdrW, hdrH);
      });
      el.addEventListener('mouseleave', function() {
        popupHeader.style.opacity = '0';
      });
    })(hdrHits[i]);
  }

  var ftrHits = svg.querySelectorAll('.footer-hit');
  for (var i = 0; i < ftrHits.length; i++) {
    (function(el) {
      el.addEventListener('mouseenter', function() {
        f1.textContent = el.getAttribute('data-line1');
        f2.textContent = el.getAttribute('data-line2');
        popupFooter.style.opacity = '1';
        popupHeader.style.opacity = '0';
      });
      el.addEventListener('mousemove', function(evt) {
        position(popupFooter, svgPoint(evt), ftrW, ftrH);
      });
      el.addEventListener('mouseleave', function() {
        popupFooter.style.opacity = '0';
      });
    })(ftrHits[i]);
  }
})();
